--
-- Table structure for table `audit_assays`
--

DROP TABLE IF EXISTS `audit_assays`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `audit_assays` (
  `audit_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `operation` enum('INSERT','UPDATE','DELETE') NOT NULL,
  `assay_id` mediumint(8) unsigned DEFAULT NULL,
  `test_id` mediumint(8) unsigned DEFAULT NULL,
  `method_id` tinyint(3) unsigned DEFAULT NULL,
  `unit_id` tinyint(3) unsigned DEFAULT NULL,
  `sample_id` tinyint(3) unsigned DEFAULT NULL,
  `category_id` tinyint(3) unsigned DEFAULT NULL,
  `org_id` int(11) unsigned DEFAULT NULL,
  `code` varchar(10) DEFAULT NULL,
  `description` varchar(100) DEFAULT NULL,
  `loinc_code` varchar(20) DEFAULT NULL,
  `cvw` float unsigned DEFAULT NULL,
  `cvb` float unsigned DEFAULT NULL,
  `imp` float unsigned DEFAULT NULL,
  `bias` float unsigned DEFAULT NULL,
  `teap005` float unsigned DEFAULT NULL,
  `teap001` float unsigned DEFAULT NULL,
  `to_export` tinyint(1) DEFAULT NULL,
  `is_mandatory` tinyint(1) DEFAULT NULL,
  `status` tinyint(1) DEFAULT NULL,
  `log_time` timestamp NOT NULL DEFAULT current_timestamp(),
  `log_id` int(10) unsigned DEFAULT NULL COMMENT 'User who made the change',
  `log_ip` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`audit_id`),
  KEY `idx_audit_assays_assay` (`assay_id`),
  KEY `idx_audit_assays_time` (`log_time`),
  KEY `idx_audit_assays_user` (`log_id`)
) ENGINE=InnoDB AUTO_INCREMENT=475 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

