CREATE TABLE `audit_results` (
  `audit_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `operation` enum('INSERT','UPDATE','DELETE','VOID') NOT NULL,
  `result_id` bigint(20) unsigned NOT NULL,
